#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXK 1000000

int freq[MAXK + 5];

int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n, k, d;
        scanf("%d %d %d", &n, &k, &d);
        int *a = (int*)malloc(sizeof(int) * n);
        for (int i = 0; i < n; i++) {
            scanf("%d", &a[i]);
        }

        memset(freq, 0, sizeof(int) * (k + 2));

        int distinct = 0;
        for (int i = 0; i < d; i++) {
            if (freq[a[i]] == 0) distinct++;
            freq[a[i]]++;
        }
        int ans = distinct;

        for (int i = d; i < n; i++) {
            freq[a[i - d]]--;
            if (freq[a[i - d]] == 0) distinct--;

            if (freq[a[i]] == 0) distinct++;
            freq[a[i]]++;

            if (distinct < ans) ans = distinct;
        }

        printf("%d\n", ans);
        free(a);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    long long a, b;
} Pair;

int cmp(const void *x, const void *y) {
    Pair *p = (Pair *)x;
    Pair *q = (Pair *)y;
    if (p->a < q->a) return -1;
    if (p->a > q->a) return 1;
    return 0;
}

int main() {
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);

        Pair *arr = malloc(sizeof(Pair) * n);
        long long total_b = 0;

        for (int i = 0; i < n; i++) scanf("%lld", &arr[i].a);
        for (int i = 0; i < n; i++) {
            scanf("%lld", &arr[i].b);
            total_b += arr[i].b;
        }

        qsort(arr, n, sizeof(Pair), cmp);

        long long ans = LLONG_MAX;
        long long prefix_b = 0;

        for (int i = 0; i < n; i++) {
            prefix_b += arr[i].b;
            long long max_a = arr[i].a;
            long long remain_b = total_b - prefix_b;
            long long candidate = (max_a > remain_b ? max_a : remain_b);
            if (candidate < ans) ans = candidate;
        }

        long long max_a = 0;
        for (int i = 0; i < n; i++) if (arr[i].a > max_a) max_a = arr[i].a;
        if (max_a < ans) ans = max_a;

        if (total_b < ans) ans = total_b;

        printf("%lld\n", ans);
        free(arr);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int maxE = 2*(N-1) + 5;
    int *to = (int*)malloc(maxE * sizeof(int));
    int *next = (int*)malloc(maxE * sizeof(int));
    int *head = (int*)malloc((N+1) * sizeof(int));
    for (int i = 1; i <= N; ++i) head[i] = -1;
    int eidx = 0;

    int a, b;
    for (int i = 0; i < N-1; ++i) {
        scanf("%d %d", &a, &b);
        // add a->b
        to[eidx] = b; next[eidx] = head[a]; head[a] = eidx++;
        // add b->a
        to[eidx] = a; next[eidx] = head[b]; head[b] = eidx++;
    }

    int *d1 = (int*)malloc((N+1) * sizeof(int));
    int *dN = (int*)malloc((N+1) * sizeof(int));
    for (int i = 1; i <= N; ++i) { d1[i] = -1; dN[i] = -1; }

    // simple queue
    int *q = (int*)malloc((N+5) * sizeof(int));
    int front, rear;

    // BFS from 1 -> d1
    front = rear = 0;
    q[rear++] = 1; d1[1] = 0;
    while (front < rear) {
        int v = q[front++];
        for (int ei = head[v]; ei != -1; ei = next[ei]) {
            int u = to[ei];
            if (d1[u] == -1) {
                d1[u] = d1[v] + 1;
                q[rear++] = u;
            }
        }
    }

    // BFS from N -> dN
    front = rear = 0;
    q[rear++] = N; dN[N] = 0;
    while (front < rear) {
        int v = q[front++];
        for (int ei = head[v]; ei != -1; ei = next[ei]) {
            int u = to[ei];
            if (dN[u] == -1) {
                dN[u] = dN[v] + 1;
                q[rear++] = u;
            }
        }
    }

    int cnt = 0;
    for (int i = 1; i <= N; ++i) {
        if (d1[i] <= dN[i]) cnt++;
    }

    if (cnt > N - cnt) printf("Fennec\n");
    else printf("Snuke\n");

    free(to); free(next); free(head);
    free(d1); free(dN); free(q);
    return 0;
}

#include <stdio.h>

int main() {
    int N;
    long long A, B;
    scanf("%d %lld %lld", &N, &A, &B);

    long long X[N];
    for (int i = 0; i < N; i++) {
        scanf("%lld", &X[i]);
    }

    long long ans = 0;
    for (int i = 0; i < N - 1; i++) {
        long long walk_cost = A * (X[i+1] - X[i]);
        long long teleport_cost = B;
        ans += (walk_cost < teleport_cost ? walk_cost : teleport_cost);
    }

    printf("%lld\n", ans);
    return 0;
}
